import Component from 'flarum/common/Component';
let gradients = 0;

/**
 * Where the line and the entry marker go in the 100×30 box: time across, price up,
 * with the member's entry price included in the vertical range so its marker fits.
 */
function geometry(raw, entry) {
  const points = raw.length ? raw : [[0, 10]];
  const line = points.length === 1 ? [points[0], [points[0][0] + 1, points[0][1]]] : points;
  const t0 = line[0][0];
  const t1 = Math.max(t0 + 1, line[line.length - 1][0]);
  const prices = line.map(p => p[1]).concat(entry ? [entry.price] : []);
  const lo = Math.min(...prices);
  const hi = Math.max(...prices, lo + 1);
  const x = at => (at - t0) / (t1 - t0) * 100;
  const y = p => 28 - (p - lo) / (hi - lo) * 24;
  return {
    coords: line.map(([at, p]) => `${x(at).toFixed(2)},${y(p).toFixed(2)}`),
    entryX: entry && entry.at >= t0 ? x(Math.min(entry.at, t1)) : null
  };
}

/**
 * The price line: an SVG polyline over an area fill, scaled to its own box
 * (preserveAspectRatio none, non-scaling stroke). Colour comes from
 * currentColor, so the trend class and any theme decide it.
 */
export default class Sparkline extends Component {
  id = `HypeSpark-${++gradients}`;
  view() {
    const {
      coords,
      entryX
    } = geometry(this.attrs.points, this.attrs.entry ?? null);
    return m("svg", {
      className: 'HypeSparkline ' + (this.attrs.className || ''),
      viewBox: "0 0 100 30",
      preserveAspectRatio: "none",
      role: this.attrs.label ? 'img' : undefined,
      "aria-label": this.attrs.label,
      "aria-hidden": this.attrs.label ? undefined : 'true',
      focusable: "false"
    }, m("defs", null, m("linearGradient", {
      id: this.id,
      x1: "0",
      x2: "0",
      y1: "0",
      y2: "1"
    }, m("stop", {
      offset: "0",
      "stop-color": "currentColor",
      "stop-opacity": "0.28"
    }), m("stop", {
      offset: "1",
      "stop-color": "currentColor",
      "stop-opacity": "0"
    }))), m("polygon", {
      points: `0,30 ${coords.join(' ')} 100,30`,
      fill: `url(#${this.id})`
    }), m("polyline", {
      points: coords.join(' '),
      fill: "none",
      stroke: "currentColor",
      "stroke-width": "2",
      "vector-effect": "non-scaling-stroke",
      "stroke-linejoin": "round",
      "stroke-linecap": "round"
    }), entryX !== null ? m("line", {
      className: "HypeSparkline-entry",
      x1: entryX,
      x2: entryX,
      y1: "0",
      y2: "30",
      stroke: "currentColor",
      "stroke-width": "1",
      "stroke-dasharray": "2 2",
      "vector-effect": "non-scaling-stroke"
    }) : null);
  }
}
flarum.reg.add('ernestdefoe-hype-market', 'forum/components/Sparkline', Sparkline);